import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Projects and environments","description":"","frontmatter":{},"headers":[],"relativePath":"guide/projects.md","filePath":"guide/projects.md"}'),i={name:"guide/projects.md"};function r(o,e,c,l,p,d){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="projects-and-environments" tabindex="-1">Projects and environments <a class="header-anchor" href="#projects-and-environments" aria-label="Permalink to &quot;Projects and environments&quot;">​</a></h1><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects {#projects}&quot;">​</a></h2><p>A project groups the applications and databases of one product. Each project starts with a <strong>production</strong> environment and can have <strong>staging</strong> and <strong>development</strong> too.</p><ul><li><p>Each environment is separate: its own services, variables, databases and addresses. An application only reaches the databases of its own environment.</p></li><li><p>On the server, each environment is a Kubernetes namespace named <code>orbit-&lt;project&gt;-&lt;environment&gt;</code>, with the name the project was created with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy,pods,ingress,certificates</span></span></code></pre></div></li></ul><h2 id="changing" tabindex="-1">Changing and deleting <a class="header-anchor" href="#changing" aria-label="Permalink to &quot;Changing and deleting {#changing}&quot;">​</a></h2><p>A project&#39;s <strong>Settings</strong>, next to its environments:</p><ul><li><strong>Name, description and color.</strong> A new name must not be one another project uses or used. What already runs keeps its namespace and addresses; only services added later take the new name in their generated address.</li><li><strong>Removing staging or development.</strong> Everything in it stops and is removed with its data, and previews that copied it are turned off. Production stays while the project exists.</li><li><strong>Deleting the project.</strong> Every environment, preview, application and database goes, with their data.</li><li><strong>Deleting an application</strong> is at the bottom of its Settings. A <strong>database</strong> has the same section on its page and is refused while an application still references it: disconnect it first.</li></ul><p>Every removal asks you to type the name. Backup files are kept: local ones under <code>/var/lib/orbit/backups/&lt;database id&gt;</code>, external ones in their bucket.</p><h2 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces {#workspaces}&quot;">​</a></h2><ul><li><strong>What belongs to a workspace:</strong> projects (with their environments, services, databases and backups), the GitHub, GitLab and Bitbucket connections, registry credentials, backup storages and activity. Servers are shared by every workspace.</li><li><strong>Switching:</strong> the switcher at the top of the sidebar. Each browser remembers the last one it used, and opening a link to a project in another workspace switches to it.</li><li><strong>GitHub, GitLab and Bitbucket per workspace:</strong> each workspace connects its own GitHub account or organization, its own GitLab and its own Bitbucket workspace, so a &quot;Personal&quot; workspace can read your account while a &quot;Cortex Labs&quot; one reads the organization.</li><li><strong>Names:</strong> project names are unique across the whole Orbit, because they name the Kubernetes namespace and the generated address.</li><li><strong>Creating and renaming:</strong> in Settings → Workspace. Only Orbit&#39;s administrator creates workspaces.</li><li><strong>People:</strong> each workspace has its own members and roles. See <a href="./members">Members and roles</a>.</li></ul>',10)])])}const k=t(i,[["render",r]]);export{g as __pageData,k as default};
